import { StyleSheet } from 'react-native';
import { colors, spacing } from '../theme';

export default StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.background,
  },
  content: {
    padding: spacing.lg,
  },
  metricsRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  cardLarge: {
    backgroundColor: colors.card,
    borderRadius: 28,
    padding: spacing.lg,
    marginTop: spacing.lg,
    borderWidth: 1,
    borderColor: colors.border,
    shadowColor: colors.primary,
    shadowOpacity: 0.12,
    shadowOffset: { width: 0, height: 18 },
    shadowRadius: 30,
    elevation: 8,
  },
  sectionTitle: {
    color: colors.text,
    fontSize: 18,
    fontWeight: '700',
  },
  sectionValue: {
    color: colors.primary,
    fontSize: 26,
    fontWeight: '900',
    marginTop: spacing.sm,
  },
  sectionDescription: {
    color: colors.muted,
    marginTop: spacing.sm,
    fontSize: 14,
    lineHeight: 20,
  },
  buttonRow: {
    flexDirection: 'row',
    marginTop: spacing.lg,
  },
  actionButton: {
    flex: 1,
    backgroundColor: colors.surface,
    borderRadius: 18,
    padding: spacing.md,
    marginRight: spacing.sm,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 1,
    borderColor: colors.border,
  },
  actionText: {
    color: colors.text,
    marginLeft: spacing.xs,
    fontWeight: '700',
  },
  statusCard: {
    marginTop: spacing.lg,
    backgroundColor: colors.card,
    borderRadius: 26,
    padding: spacing.lg,
    borderWidth: 1,
    borderColor: colors.border,
  },
  statusRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: spacing.md,
  },
  statusLabel: {
    color: colors.text,
    fontWeight: '600',
  },
  statusValue: {
    color: colors.primary,
    fontWeight: '700',
  },
  alertCard: {
    marginTop: spacing.lg,
    backgroundColor: colors.card,
    borderRadius: 26,
    padding: spacing.lg,
    borderWidth: 1,
    borderColor: colors.border,
  },
  alertRow: {
    marginTop: spacing.md,
  },
  alertName: {
    color: colors.text,
    fontWeight: '700',
  },
  alertBadge: {
    color: colors.primary,
    marginTop: spacing.xs,
  },
  linkButton: {
    marginTop: spacing.lg,
    alignItems: 'center',
  },
  linkText: {
    color: colors.primary,
    fontWeight: '700',
  },
});
